DELIMITER ;;

DROP PROCEDURE IF EXISTS `sp_cap_nhat_tong_hoa_don`;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_cap_nhat_tong_hoa_don`(IN p_MaHoaDon INT)
BEGIN
    DECLARE v_tong DECIMAL(12,2);
    DECLARE v_giam DECIMAL(12,2);
    DECLARE v_bh DECIMAL(12,2);

    SELECT COALESCE(SUM(ThanhTien), 0.00)
      INTO v_tong
      FROM CHI_TIET_HOA_DON
     WHERE MaHoaDon = p_MaHoaDon;

    SELECT GiamGia, BaoHiemChiTra
      INTO v_giam, v_bh
      FROM HOA_DON
     WHERE MaHoaDon = p_MaHoaDon;

    IF v_giam + v_bh > v_tong THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Giam gia va bao hiem khong duoc vuot TongTien moi';
    END IF;

    UPDATE HOA_DON
       SET TongTien = v_tong,
           BenhNhanChiTra = v_tong - v_giam - v_bh
     WHERE MaHoaDon = p_MaHoaDon;
END;;

DROP PROCEDURE IF EXISTS `sp_dat_lich_hen`;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_dat_lich_hen`(
    IN p_MaBenhNhan INT,
    IN p_MaCaKham INT,
    IN p_LyDoKham TEXT
)
BEGIN
    DECLARE v_suc_chua INT;
    DECLARE v_da_dat INT;
    DECLARE v_trang_thai_ca VARCHAR(30);

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;
    SELECT SoLuongTiepNhan, TrangThai
      INTO v_suc_chua, v_trang_thai_ca
      FROM CA_KHAM
     WHERE MaCaKham = p_MaCaKham
     FOR UPDATE;

    IF v_trang_thai_ca <> 'CON_TRONG' THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Ca kham khong o trang thai con trong';
    END IF;

    SELECT COUNT(*) INTO v_da_dat
      FROM LICH_HEN
     WHERE MaCaKham = p_MaCaKham
       AND TrangThai IN ('CHO_XAC_NHAN','DA_XAC_NHAN','DA_TIEP_NHAN');

    IF v_da_dat >= v_suc_chua THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Ca kham da het so luong tiep nhan';
    END IF;

    VALUES (p_MaBenhNhan, p_MaCaKham, p_LyDoKham);
    COMMIT;
END;;

DELIMITER ;

