DELIMITER ;;

DROP TRIGGER IF EXISTS `trg_cakham_bi_kiemtra_gio`;;
CREATE DEFINER=`root`@`localhost` TRIGGER `trg_cakham_bi_kiemtra_gio` BEFORE INSERT ON `ca_kham` FOR EACH ROW BEGIN
    DECLARE v_gio_bat_dau TIME;
    DECLARE v_gio_ket_thuc TIME;
    SELECT GioBatDau, GioKetThuc
      INTO v_gio_bat_dau, v_gio_ket_thuc
      FROM LICH_LAM_VIEC
     WHERE MaLichLamViec = NEW.MaLichLamViec;
    IF NEW.GioBatDau < v_gio_bat_dau OR NEW.GioKetThuc > v_gio_ket_thuc THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Gio ca kham phai nam trong gio lam viec cua bac si';
    END IF;
END;;

DROP TRIGGER IF EXISTS `trg_cakham_bu_kiemtra_gio`;;
CREATE DEFINER=`root`@`localhost` TRIGGER `trg_cakham_bu_kiemtra_gio` BEFORE UPDATE ON `ca_kham` FOR EACH ROW BEGIN
    DECLARE v_gio_bat_dau TIME;
    DECLARE v_gio_ket_thuc TIME;
    SELECT GioBatDau, GioKetThuc
      INTO v_gio_bat_dau, v_gio_ket_thuc
      FROM LICH_LAM_VIEC
     WHERE MaLichLamViec = NEW.MaLichLamViec;
    IF NEW.GioBatDau < v_gio_bat_dau OR NEW.GioKetThuc > v_gio_ket_thuc THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Gio ca kham phai nam trong gio lam viec cua bac si';
    END IF;
END;;

DROP TRIGGER IF EXISTS `trg_cthoadon_before_insert`;;
CREATE DEFINER=`root`@`localhost` TRIGGER `trg_cthoadon_before_insert` BEFORE INSERT ON `chi_tiet_hoa_don` FOR EACH ROW BEGIN
    IF NOT (
        (NEW.LoaiChiPhi = 'DICH_VU'
            AND NEW.MaChiDinh IS NOT NULL
            AND NEW.MaChiTietDonThuoc IS NULL)
        OR
        (NEW.LoaiChiPhi = 'THUOC'
            AND NEW.MaChiTietDonThuoc IS NOT NULL
            AND NEW.MaChiDinh IS NULL)
        OR
        (NEW.LoaiChiPhi IN ('KHAM', 'KHAC')
            AND NEW.MaChiDinh IS NULL
            AND NEW.MaChiTietDonThuoc IS NULL)
    ) THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Loai chi phi khong khop voi nguon chi phi';
    END IF;
END;;

DROP TRIGGER IF EXISTS `trg_cthoadon_ai`;;
CREATE DEFINER=`root`@`localhost` TRIGGER `trg_cthoadon_ai` AFTER INSERT ON `chi_tiet_hoa_don` FOR EACH ROW BEGIN
    CALL sp_cap_nhat_tong_hoa_don(NEW.MaHoaDon);
END;;

DROP TRIGGER IF EXISTS `trg_cthoadon_before_update`;;
CREATE DEFINER=`root`@`localhost` TRIGGER `trg_cthoadon_before_update` BEFORE UPDATE ON `chi_tiet_hoa_don` FOR EACH ROW BEGIN
    IF NOT (
        (NEW.LoaiChiPhi = 'DICH_VU'
            AND NEW.MaChiDinh IS NOT NULL
            AND NEW.MaChiTietDonThuoc IS NULL)
        OR
        (NEW.LoaiChiPhi = 'THUOC'
            AND NEW.MaChiTietDonThuoc IS NOT NULL
            AND NEW.MaChiDinh IS NULL)
        OR
        (NEW.LoaiChiPhi IN ('KHAM', 'KHAC')
            AND NEW.MaChiDinh IS NULL
            AND NEW.MaChiTietDonThuoc IS NULL)
    ) THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Loai chi phi khong khop voi nguon chi phi';
    END IF;
END;;

DROP TRIGGER IF EXISTS `trg_cthoadon_au`;;
CREATE DEFINER=`root`@`localhost` TRIGGER `trg_cthoadon_au` AFTER UPDATE ON `chi_tiet_hoa_don` FOR EACH ROW BEGIN
    CALL sp_cap_nhat_tong_hoa_don(OLD.MaHoaDon);
    IF NEW.MaHoaDon <> OLD.MaHoaDon THEN
        CALL sp_cap_nhat_tong_hoa_don(NEW.MaHoaDon);
    END IF;
END;;

DROP TRIGGER IF EXISTS `trg_cthoadon_ad`;;
CREATE DEFINER=`root`@`localhost` TRIGGER `trg_cthoadon_ad` AFTER DELETE ON `chi_tiet_hoa_don` FOR EACH ROW BEGIN
    CALL sp_cap_nhat_tong_hoa_don(OLD.MaHoaDon);
END;;

DROP TRIGGER IF EXISTS `trg_lichlamviec_bu_kiemtra_ca`;;
CREATE DEFINER=`root`@`localhost` TRIGGER `trg_lichlamviec_bu_kiemtra_ca` BEFORE UPDATE ON `lich_lam_viec` FOR EACH ROW BEGIN
    IF EXISTS (
        SELECT 1 FROM CA_KHAM
         WHERE MaLichLamViec = OLD.MaLichLamViec
           AND (GioBatDau < NEW.GioBatDau OR GioKetThuc > NEW.GioKetThuc)
    ) THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Khung gio moi khong bao phu cac ca kham da tao';
    END IF;
END;;

DELIMITER ;

SET FOREIGN_KEY_CHECKS=1;
